    /* ========================================================
       6. ARTICLE <-> TAG SAMPLE RELATIONSHIPS
       ======================================================== */

    INSERT INTO ArticleTag (ArticleId, TagId)
    SELECT a.ArticleId, t.TagId
    FROM NewsArticle a
    CROSS JOIN Tag t
    WHERE
        (a.Title = N'SmartNews thử nghiệm mô hình tổng hợp tin đa nguồn'
            AND t.TagName IN (N'AI', N'Công nghệ'))
        OR
        (a.Title = N'Vì sao một sự kiện nên được đọc từ nhiều nguồn'
            AND t.TagName IN (N'Giáo dục', N'Công nghệ'))
        OR
        (a.Title = N'Cách SmartNews hiển thị nguồn gốc của thông tin'
            AND t.TagName IN (N'Công nghệ', N'Chính trị'))
        OR
        (a.Title = N'Bản thử nghiệm trang Story dành cho tin quốc tế'
            AND t.TagName IN (N'Quốc tế'))
        OR
        (a.Title = N'Ứng dụng AI trong việc tóm tắt và so sánh nguồn tin'
            AND t.TagName IN (N'AI', N'Công nghệ'))
        OR
        (a.Title = N'Thiết kế trải nghiệm đọc tin ngắn gọn nhưng vẫn có nguồn'
            AND t.TagName IN (N'Đời sống', N'Công nghệ'))
        OR
        (a.Title = N'Thử nghiệm dashboard thống kê nội dung thể thao'
            AND t.TagName IN (N'Thể thao'))
        OR
        (a.Title = N'Kiểm thử chuyên mục kinh doanh trên SmartNews'
            AND t.TagName IN (N'Kinh tế'))
        OR
        (a.Title = N'Bài viết mẫu cho chuyên mục sức khỏe'
            AND t.TagName IN (N'Sức khỏe'))
        OR
        (a.Title = N'Bản nháp kiểm thử quy trình biên tập'
            AND t.TagName IN (N'Đời sống'));


